using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["featureFlags"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/{section}", Name = "Config Section",
        MimeType = "application/json"),
     Description("Returns a specific section of the application configuration.")]
    public static string GetConfigSection(string section)
    {
        if (AppConfig.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = true });
        }

        return JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Updates a top-level configuration value by key.")]
    public static string UpdateConfig(
        [Description("The configuration key to update")] string key,
        [Description("The new value (as a string)")] string value)
    {
        return $"Configuration key '{key}' would be updated to '{value}'. (Demo only — not persisted.)";
    }

    [McpServerTool, Description("Lists all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join(", ", new[] { "environment", "maxRetries", "timeoutSeconds", "featureFlags" });
    }
}

